/**
 * ClinicalDocumentViewer — shared component for rendering clinical document content.
 *
 * Handles two formats:
 *   - CDA/C-CDA ('ccda'): the raw document transformed by /xslt/cda.xsl, shown in
 *     an isolated iframe (see _renderCDAWithXSLT)
 *   - FHIR Bundle ('fhir'): groups resources by type and shows each resource's
 *     narrative (Resource.text.div, or one generated by POST /api/fhir/narrative/:type)
 *
 * Both documents come from outside (a partner's CDA, a received FHIR bundle), so
 * neither may run script in the application:
 *   - the CDA rendering goes into an iframe with an empty sandbox (no scripts,
 *     opaque origin) via srcdoc — nothing in it can reach the application;
 *   - FHIR narratives pass through HtmlSafe.sanitize (FHIR's own narrative
 *     rules: formatting elements only, no scripts or event attributes).
 *
 * Usage:
 *   const viewer = new ClinicalDocumentViewer(containerEl, {
 *       interfaceId: '...', messageId: '...', format: 'ccda'
 *   });
 *   await viewer.mount();
 */
class ClinicalDocumentViewer {
    constructor(container, options) {
        options = options || {};
        this._container     = container;
        this._interfaceId   = options.interfaceId   || null;
        this._messageId     = options.messageId     || null;
        this._format        = options.format        || 'ccda';
        this._parsedContent = options.parsedContent || null;
        this._activeSection = null;

        this._tpl = {
            loading:     () => HtmlSafe.html`<div style="display:flex;align-items:center;justify-content:center;height:100%;min-height:120px;color:#94a3b8;font-size:0.85rem;"><i class="fas fa-spinner fa-spin" style="margin-right:0.5rem;"></i> Loading clinical document...</div>`,
            unavailable: () => HtmlSafe.html`<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;min-height:120px;color:#94a3b8;text-align:center;padding:1.5rem;"><i class="fas fa-file-medical" style="font-size:2rem;margin-bottom:0.75rem;"></i><div style="font-weight:600;color:#64748b;margin-bottom:0.35rem;">Clinical document not available</div><div style="font-size:0.8rem;">Parsed content may still be processing or object storage may be unavailable.</div></div>`,
            empty:       (msg) => HtmlSafe.html`<div style="color:#94a3b8;font-size:0.82rem;padding:1rem 0;">${msg}</div>`,
        };
    }

    // ── Public API ─────────────────────────────────────────────────────────────

    async mount() {
        this._container.innerHTML = HtmlSafe.html`${this._tpl.loading()}`;

        if (this._format === 'ccda') {
            await this._renderCDAWithXSLT();
            return;
        }

        // FHIR path: use parsedContent passed in directly, or fetch sections
        if (!this._parsedContent && this._interfaceId && this._messageId) {
            await this._fetchParsedContent();
        }
        if (!this._parsedContent) {
            this._container.innerHTML = HtmlSafe.html`${this._tpl.unavailable()}`;
            return;
        }
        await this._renderFHIR();
    }

    destroy() {
        this._container.innerHTML = '';
    }

    // ── XSLT-based CDA rendering ──────────────────────────────────────────────

    async _renderCDAWithXSLT() {
        try {
            // Fetch raw XML and XSLT stylesheet in parallel
            const [rawXml, xsltText] = await Promise.all([
                this._fetchRawXml(),
                this._loadXSLT(),
            ]);

            if (!rawXml || !xsltText) {
                this._container.innerHTML = HtmlSafe.html`${this._tpl.unavailable()}`;
                return;
            }

            const parser  = new DOMParser();
            const xmlDoc  = parser.parseFromString(rawXml,  'application/xml');
            const xsltDoc = parser.parseFromString(xsltText, 'application/xml');

            // Abort on parse errors
            if (xmlDoc.querySelector('parsererror') || xsltDoc.querySelector('parsererror')) {
                console.warn('[ClinicalDocumentViewer] XML/XSLT parse error');
                this._container.innerHTML = HtmlSafe.html`${this._tpl.unavailable()}`;
                return;
            }

            const proc = new XSLTProcessor();
            proc.importStylesheet(xsltDoc);
            const resultDoc = proc.transformToDocument(xmlDoc);

            if (!resultDoc || !resultDoc.documentElement) {
                this._container.innerHTML = HtmlSafe.html`${this._tpl.unavailable()}`;
                return;
            }

            // The rendered document comes from a partner's CDA. An empty sandbox
            // gives the iframe an opaque origin and no script execution: links,
            // handlers or script the stylesheet passes through cannot run or reach
            // the application. (allow-scripts + allow-same-origin together would
            // disable the sandbox entirely.)
            const html = new XMLSerializer().serializeToString(resultDoc).replace(/^<\?xml[^?]*\?>/, '');
            this._container.innerHTML = '';
            const iframe = document.createElement('iframe');
            iframe.style.cssText = 'width:100%;height:100%;border:none;display:block;';
            iframe.setAttribute('sandbox', '');
            iframe.setAttribute('referrerpolicy', 'no-referrer');
            iframe.title = 'Clinical document';
            iframe.srcdoc = '<!DOCTYPE html>' + html;
            this._container.style.overflow = 'hidden';
            this._container.appendChild(iframe);

        } catch (err) {
            console.warn('[ClinicalDocumentViewer] XSLT render failed:', err.message);
            this._container.innerHTML = HtmlSafe.html`${this._tpl.unavailable()}`;
        }
    }

    async _fetchRawXml() {
        if (!this._interfaceId || !this._messageId) return null;
        try {
            const url = '/api/messages/' + encodeURIComponent(this._messageId) +
                        '/raw?interfaceId=' + encodeURIComponent(this._interfaceId);
            const resp = await fetch(url);
            if (!resp.ok) return null;
            const data = await resp.json();
            return (data && data.success && data.content) ? data.content : null;
        } catch (_) { return null; }
    }

    async _loadXSLT() {
        if (ClinicalDocumentViewer._xsltCache) return ClinicalDocumentViewer._xsltCache;
        try {
            const resp = await fetch('/xslt/cda.xsl');
            if (!resp.ok) return null;
            const text = await resp.text();
            ClinicalDocumentViewer._xsltCache = text;
            return text;
        } catch (_) { return null; }
    }

    // ── FHIR rendering ─────────────────────────────────────────────────────────

    async _renderFHIR() {
        var content = this._parsedContent;
        var bundle = (content.resourceType === 'Bundle') ? content
                   : (content.bundle || content.fhirBundle || null);
        var entries = (bundle && bundle.entry) ? bundle.entry : (content.entry || []);
        var resources = entries.map(function(e) { return e.resource || e; })
                               .filter(function(r) { return r && r.resourceType; });

        if (resources.length === 0) {
            this._container.innerHTML = HtmlSafe.html`${this._tpl.empty('No FHIR resources found')}`;
            return;
        }

        var groups = {};
        resources.forEach(function(r) {
            var rt = r.resourceType;
            if (!groups[rt]) groups[rt] = [];
            groups[rt].push(r);
        });

        var narrativeMap = await this._fetchFHIRNarratives(groups);
        var resourceTypes = Object.keys(groups);
        this._activeSection = resourceTypes[0];

        this._container.innerHTML = HtmlSafe.html`<div class="cdv-root" style="display:flex;flex-direction:column;height:100%;background:#fff;border-radius:8px;overflow:hidden;border:1px solid #e2e8f0;">${
            this._renderFHIRFormatBadge(resources.length)}${
            this._renderFHIRTabs(resourceTypes, groups)}<div class="cdv-content" style="flex:1;overflow:auto;padding:1rem;">${
            this._fhirSectionContent(this._activeSection, groups, narrativeMap)}</div></div>`;

        this._attachFHIRTabListeners(resourceTypes, groups, narrativeMap);
    }

    async _fetchFHIRNarratives(groups) {
        var narrativeMap = {};
        var fetchPromises = [];

        for (var rt in groups) {
            if (!groups.hasOwnProperty(rt)) continue;
            var resources = groups[rt];
            for (var i = 0; i < resources.length; i++) {
                var r = resources[i];
                if (r.text && r.text.div) continue;
                var key = rt + ':' + i;
                fetchPromises.push(
                    (function(k, resource, rtype) {
                        return fetch('/api/fhir/narrative/' + encodeURIComponent(rtype), {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(resource)
                        })
                        .then(function(resp) { return resp.ok ? resp.json() : null; })
                        .then(function(data) {
                            if (data && data.success && data.narrative) narrativeMap[k] = data.narrative;
                        })
                        .catch(function() {});
                    })(key, r, rt)
                );
            }
        }

        await Promise.allSettled(fetchPromises);
        return narrativeMap;
    }

    _renderFHIRFormatBadge(count) {
        return HtmlSafe.html`<div style="padding:0.5rem 1rem;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;gap:0.5rem;flex-shrink:0;"><span style="font-size:0.75rem;font-weight:700;color:#475569;text-transform:uppercase;">FHIR Resources</span><span style="background:#dcfce7;color:#166534;padding:0.15rem 0.5rem;border-radius:4px;font-size:0.72rem;font-weight:600;">R4 · ${count} resources</span></div>`;
    }

    _renderFHIRTabs(resourceTypes, groups) {
        var self = this;
        var tabs = resourceTypes.map(function(rt) {
            var label = ClinicalDocumentViewer.FHIR_RESOURCE_LABELS[rt] || rt;
            var count = groups[rt].length;
            var active = (rt === self._activeSection);
            var style = 'flex-shrink:0;padding:0.5rem 0.9rem;border:none;' +
                'background:' + (active ? '#fff' : 'transparent') + ';' +
                'border-bottom:2px solid ' + (active ? '#2563eb' : 'transparent') + ';' +
                'color:' + (active ? '#1e40af' : '#64748b') + ';' +
                'font-size:0.8rem;font-weight:' + (active ? '600' : '400') + ';cursor:pointer;white-space:nowrap;';
            return HtmlSafe.html`<button data-cdv-tab="${rt}" style="${style}">${label}<span style="background:#e2e8f0;color:#475569;padding:0.05rem 0.4rem;border-radius:10px;font-size:0.68rem;margin-left:0.3rem;">${count}</span></button>`;
        });
        return HtmlSafe.html`<div style="display:flex;overflow-x:auto;border-bottom:1px solid #e2e8f0;flex-shrink:0;background:#f8fafc;">${tabs}</div>`;
    }

    _fhirSectionContent(rt, groups, narrativeMap) {
        var resources = groups[rt] || [];
        return HtmlSafe.html`${resources.map(function(r, i) {
            var key = rt + ':' + i;
            // The narrative is XHTML from the resource (or generated from it):
            // shown as formatted text, sanitized to FHIR's narrative rules.
            var narrativeDiv = (r.text && r.text.div) ? r.text.div : (narrativeMap[key] || '');
            var instanceHeader = (resources.length > 1)
                ? HtmlSafe.html`<div style="font-size:0.72rem;font-weight:600;color:#94a3b8;margin-bottom:0.5rem;">${rt} ${i + 1} of ${resources.length}${r.id ? ' · ' + r.id : ''}</div>`
                : '';
            var narrativeContent = narrativeDiv
                ? HtmlSafe.html`<div class="cdv-narrative">${HtmlSafe.sanitize(narrativeDiv)}</div>`
                : HtmlSafe.html`<div style="color:#94a3b8;font-size:0.82rem;padding:1rem 0;">No narrative available</div>`;
            var separator = i > 0 ? 'border-top:1px solid #e2e8f0;padding-top:1rem;margin-top:1rem;' : '';
            return HtmlSafe.html`<div style="${separator}">${instanceHeader}${narrativeContent}</div>`;
        })}`;
    }

    _attachFHIRTabListeners(resourceTypes, groups, narrativeMap) {
        var self = this;
        this._container.querySelectorAll('[data-cdv-tab]').forEach(function(btn) {
            btn.addEventListener('click', function() {
                var rt = btn.dataset.cdvTab;
                self._activeSection = rt;
                self._container.querySelectorAll('[data-cdv-tab]').forEach(function(b) {
                    var a = b.dataset.cdvTab === rt;
                    b.style.background   = a ? '#fff' : 'transparent';
                    b.style.borderBottom = '2px solid ' + (a ? '#2563eb' : 'transparent');
                    b.style.color        = a ? '#1e40af' : '#64748b';
                    b.style.fontWeight   = a ? '600' : '400';
                });
                var contentEl = self._container.querySelector('.cdv-content');
                if (contentEl) contentEl.innerHTML = HtmlSafe.html`${self._fhirSectionContent(rt, groups, narrativeMap)}`;
            });
        });
    }
}

ClinicalDocumentViewer._xsltCache = null;

ClinicalDocumentViewer.FHIR_RESOURCE_LABELS = {
    Patient:             'Patient Demographics',
    AllergyIntolerance:  'Allergy and Intolerance',
    Condition:           'Problem',
    MedicationStatement: 'Medication',
    Observation:         'Clinical Observation',
    Immunization:        'Immunization',
    Procedure:           'Procedure',
    Bundle:              'Document',
};
